/**
 * P4c task 1: the ja lexicon for ja-vi (content/ja/lexicon/lexemes.json, generated by
 * content/ja/_drafts/_generators/ja-lex.py) — what the generic lexicon validator does not check.
 */
import { describe, expect, test } from "bun:test";

import { richLexiconSchema, type PackSource } from "../../content/schema";
import { legacyUnmappedRel, loadLegacyUnmapped, readJson } from "../lib/pipeline";

const lexicon = richLexiconSchema("ja").parse(readJson("content/ja/lexicon/lexemes.json"));
const HAN = /[㐀-鿿豈-﫿々〆ヶ]/u;

describe("ja lexicon (P4c)", () => {
  test("about 900 lexemes, every one with a Vietnamese gloss, a kana reading and a translated example", () => {
    expect(lexicon.lexemes.length).toBeGreaterThanOrEqual(850);
    expect(lexicon.lexemes.length).toBeLessThanOrEqual(1000);
    for (const lex of lexicon.lexemes) {
      expect(lex.glosses.vi?.trim().length, lex.id).toBeGreaterThan(0);
      expect(lex.glosses.vi, lex.id).not.toMatch(/^TODO/);
      expect(lex.reading?.kana, lex.id).toBe(lex.pronunciation?.value);
      expect(HAN.test(lex.surface) ? lex.reading?.furigana?.length : 1, lex.id).toBeGreaterThan(0);
      for (const ex of lex.examples) expect(ex.translations.vi, lex.id).toBeTruthy();
    }
  });

  test("ids are romaji slugs", () => {
    for (const lex of lexicon.lexemes) expect(lex.id, lex.surface).toMatch(/^ja:w:[a-z0-9]+(?:-[a-z0-9]+)*$/);
  });

  test("every ja-en word maps to a lexeme with the pack's English gloss, or is listed in legacy-unmapped.json", () => {
    const pack = readJson("content/courses/ja-en.json") as PackSource;
    const unmapped = loadLegacyUnmapped("ja");
    const bySurface = new Map(lexicon.lexemes.flatMap((l) => [l.surface, ...(l.legacySurfaces ?? [])].map((s) => [s, l] as const)));
    for (const w of pack.sections.flatMap((s) => s.units.flatMap((u) => u.words))) {
      const lex = bySurface.get(w.target);
      if (lex === undefined) expect(unmapped.get(w.target), `${w.target} (${legacyUnmappedRel("ja")})`).toBe("ja-en");
      else expect(lex.glosses.en, w.target).toBe(w.native);
    }
  });

  test("every Hán-Việt entry of ja is a lexeme surface or the noun of a する verb", () => {
    const table = readJson("content/hanviet/ja.json") as { entries: { word: string }[] };
    const surfaces = new Set(lexicon.lexemes.map((l) => l.surface));
    const course = table.entries.filter((e) => surfaces.has(e.word) || surfaces.has(`${e.word}する`));
    expect(course.length).toBeGreaterThanOrEqual(140);
  });

  test("the kanji target is about 100 and covers every N5 kanji", () => {
    const kanji = readJson("content/ja/_drafts/review/kanji.json") as { counts: { taught: number; n5InA1: number; n5Total: number } };
    expect(kanji.counts.taught).toBe(100);
    expect(kanji.counts.n5InA1).toBe(kanji.counts.n5Total);
  });
});
